var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<OrderService>();
var app = builder.Build();

app.MapPost("/orders", (OrderRequest req, OrderService svc) =>
{
    var (tier, fee) = svc.Classify(req.items, req.priority);
    return Results.Ok(new { req.items, tier, fee });
});

app.Run();

