namespace Orders;

public class OrderService
{
    public (string tier, int fee) Classify(int items, bool priority)
    {
        string tier;
        if (priority)
        {
            tier = "express";
        }
        else if (items >= 10)
        {
            tier = "bulk";
        }
        else
        {
            tier = "standard";
        }
        int fee = tier switch
        {
            "express" => 20,
            "bulk" => 5,
            _ => 10,
        };
        return (tier, fee);
    }
}

