using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class OrderTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    public OrderTests(WebApplicationFactory<Program> factory) => _factory = factory;

    private record OrderDto(int items, string tier, int fee);

    private async Task<OrderDto> Post(int items, bool priority)
    {
        var client = _factory.CreateClient();
        var res = await client.PostAsJsonAsync("/orders", new { items, priority });
        res.EnsureSuccessStatusCode();
        return (await res.Content.ReadFromJsonAsync<OrderDto>())!;
    }

    [Fact]
    public async Task SmallOrderIsStandard()
    {
        var dto = await Post(3, false);
        Assert.Equal("standard", dto.tier);
        Assert.Equal(10, dto.fee);
    }

    [Fact]
    public async Task BulkBoundaryAtTen()
    {
        var dto = await Post(10, false);
        Assert.Equal("bulk", dto.tier);
        Assert.Equal(5, dto.fee);
    }

    [Fact]
    public async Task PriorityIsExpress()
    {
        var dto = await Post(2, true);
        Assert.Equal("express", dto.tier);
        Assert.Equal(20, dto.fee);
    }

    [Fact]
    public async Task PriorityBeatsBulk()
    {
        var dto = await Post(50, true);
        Assert.Equal("express", dto.tier);
    }
}

