using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class OrderTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    public OrderTests(WebApplicationFactory<Program> factory) => _factory = factory;

    private record OrderDto(int items, string tier, int fee);

    // posts to /orders for several sizes but never asserts which tier/fee
    // comes back, so a broken classifier still passes
    [Fact]
    public async Task EndpointResponds()
    {
        var client = _factory.CreateClient();
        foreach (int items in new[] { 1, 5, 10, 50 })
        {
            var res = await client.PostAsJsonAsync("/orders", new { items, priority = false });
            res.EnsureSuccessStatusCode();
            var dto = await res.Content.ReadFromJsonAsync<OrderDto>();
            Assert.NotNull(dto);
            Assert.False(string.IsNullOrEmpty(dto!.tier));
        }
    }

    [Fact]
    public async Task PriorityEndpointResponds()
    {
        var client = _factory.CreateClient();
        var res = await client.PostAsJsonAsync("/orders", new { items = 2, priority = true });
        res.EnsureSuccessStatusCode();
    }
}
